/dts-v1/;
#include "acme-board.dtsi"

/ {
    model = "Acme Demo Board";
    compatible = "acme,demo-board";

    soc {
        i2c0: i2c@100000 {
            compatible = "acme,i2c";
            reg = <0x100000 0x1000>;
            #address-cells = <1>;
            #size-cells = <0>;
            status = "okay";

            sensor@48 {
                compatible = "acme,th02";
                reg = <0x48>;
                interrupt-parent = <&gpio1>;
                interrupts = <12 2>;
            };
        };
    };
};
